import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlLinkComponent, VlTitleComponent } from '@domg-wc/components/atom';
import { VlWizard } from '@domg-wc/components/block';
import { VlFormLabelComponent, VlInputFieldComponent } from '@domg-wc/components/form';

registerWebComponents([
    VlWizard,
    VlTitleComponent,
    VlButtonComponent,
    VlLinkComponent,
    VlFormLabelComponent,
    VlInputFieldComponent,
]);

const wizard = document.querySelector('vl-wizard');

// vl-wizard wisselt niet zelf van stap. Een klik op een stap in de voortgangsindicator vuurt vl-click-step met
// { number, step }; enkel de actieve en de vorige stappen zijn klikbaar. Zet de actieve stap dan zelf.
wizard.addEventListener('vl-click-step', (event) => {
    wizard.activeStep = event.detail.number;
});

// Volgende in stap 1 en Vorige in stap 2.
wizard.querySelector('vl-button').addEventListener('click', () => {
    wizard.activeStep += 1;
});
wizard.querySelector('vl-link').addEventListener('click', () => {
    wizard.activeStep -= 1;
});
